#!/usr/bin/env bash
# Run RQ2 fusion experiments across all four suites:
#   flux-medium (flux-demo + kani-vecdeque + pldi23), liquid-fixpoint,
#   hashtable, sorting (flux-to-lean-demo)
#
# Assumes logs for flux-medium already exist (generated by
# eval_benchmarks/rq3_table/run_lean_proofs.sh).  Builds LeanFixpoint.Eval.FusionSearch,
# builds hashtable and sorting suites, runs the fusion experiments, generates
# liquid-fixpoint results via scripts/run_rq3.py, then generates tables.
#
# Any extra arguments (e.g. --jobs 4 --filter Foo --append) are forwarded to
# run_fusion_experiments.py.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
EVAL_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"
LF_ROOT="$(cd "$EVAL_DIR/.." && pwd)"

# ── build LeanFixpoint.Eval.FusionSearch ─────────────────────────────────────

echo "==> Building Flex.Eval.FusionSearch"
(cd "$LF_ROOT" && lake build Flex.Eval.FusionSearch)

# ── build hashtable and sorting suites ───────────────────────────────────────

for dir in hashtable_lean_proofs flux_lean_demo_lean_proofs; do
    log="$EVAL_DIR/$dir/lean_proofs.log"
    time_file="$EVAL_DIR/$dir/lean_proofs.time"

    : >"$log"

    echo "==> Running lake update in $dir"
    (cd "$EVAL_DIR/$dir" && lake update) >>"$log" 2>&1 \
        || echo "lake update failed (exit $?)" >>"$log"

    echo "==> Running lake build in $dir (output -> $log)"
    start=$(date +%s%N)
    (cd "$EVAL_DIR/$dir" && lake build) >>"$log" 2>&1 \
        || echo "lake build failed (exit $?)" >>"$log"
    end=$(date +%s%N)
    elapsed_ms=$(( (end - start) / 1000000 ))
    printf "%d\n" "$elapsed_ms" >"$time_file"
done

# ── run fusion experiments (flux-medium, hashtable, sorting) ─────────────────

echo "==> Running fusion experiments"
python3 "$SCRIPT_DIR/run_fusion_experiments.py" "$@"

# ── generate liquid-fixpoint results ─────────────────────────────────────────

LF_JSON="$LF_ROOT/eval/rq3_results.json"
echo "==> Running scripts/run_rq3.py (liquid-fixpoint benchmarks)"
python3 "$LF_ROOT/scripts/run_rq3.py" --out "$LF_JSON"

# ── generate tables ───────────────────────────────────────────────────────────

echo "==> Generating tables"
python3 "$SCRIPT_DIR/make_rq2_table.py" \
    --lf-results "$LF_JSON" \
    --format both \
    --aggregate
